  updateTool: (id: string, updates: Partial<Tool>) => boolean
  removeTool: (id: string) => void
  /** Create a named tool library; returns its new id. */
  addToolLibrary: (name: string) => string
  /** Rename a library in place. No-op if the id is unknown. */
  renameToolLibrary: (id: string, name: string) => void
