  loadMeshFlatFaces: (geoId: string) => Promise<FlatFaceRecognition>
  removeGeometry: (id: string) => void
  reorderGeometry: (fromIdx: number, toIdx: number) => void
  // Geometry folders (Stage A: store/data only; the DesignTree UI is Stage B).
